"""Read-only check before copying desktop settings and History."""
import json
import os
from pathlib import Path


def inspect_storage(source, destination):
    checks = []
    overrides = source / "config" / "local_overrides.json"
    state = source / "output" / "desktop-state.json"
    checks.append("OVERRIDES: " + ("FOUND" if overrides.is_file() else "MISSING"))
    checks.append("STATE: " + ("FOUND" if state.is_file() else "MISSING"))
    value = json.loads(state.read_text(encoding="utf-8")) if state.is_file() else {}
    history_name = value.get("history_path", "output/history.sqlite3")
    if not isinstance(history_name, str) or not history_name:
        raise ValueError("Invalid history setting")
    history = Path(history_name)
    if not history.is_absolute():
        history = source / history
    location = "DEFAULT" if history.resolve() == (source / "output/history.sqlite3").resolve() else "CUSTOM"
    checks.append("HISTORY: " + ("FOUND" if history.is_file() else "MISSING") + " / " + location)
    if not destination.exists():
        status = "MISSING"
    elif not destination.is_dir():
        status = "NOT A FOLDER"
    else:
        status = "NOT EMPTY" if any(destination.iterdir()) else "EMPTY"
    checks.append("DESTINATION: " + status)
    return checks


def main():
    try:
        profile = os.environ.get("LOCALAPPDATA", "")
        if not profile or not Path(profile).is_absolute():
            raise ValueError("User profile unavailable")
        checks = inspect_storage(
            Path(__file__).resolve().parent,
            Path(profile) / "AppHealthChecker",
        )
        print("\n".join(checks))
    except Exception as exc:
        print("PREFLIGHT ERROR: " + type(exc).__name__)


if __name__ == "__main__":
    main()
